#include "window.h"
#include <QtWidgets>
#include <QSettings>
void Window::reloadDevices(){
 QString previous=devices_->currentData().toString();if(previous.isEmpty())previous=QSettings(settingsFile_,QSettings::IniFormat).value("rx/device").toString();devices_->clear();for(auto d:Receiver::deviceInfos())devices_->addItem(d.name,d.key);int selected=devices_->findData(previous);if(selected>=0)devices_->setCurrentIndex(selected);
}
void Window::receiverOptions(){
 QSettings s(settingsFile_,QSettings::IniFormat);QDialog dialog(this);dialog.setWindowTitle("Récepteur SDR — réglages appliqués au matériel");auto form=new QFormLayout(&dialog);bool hack=devices_->currentData().toString().startsWith("hackrf:");auto automatic=new QCheckBox("Gain automatique RTL-SDR");automatic->setEnabled(!hack);automatic->setChecked(!hack&&s.value("rx/agc",false).toBool());form->addRow(automatic);auto rate=new QComboBox;for(int r:hack?QList<int>{2000000,4000000,8000000,10000000,20000000}:QList<int>{240000,256000,1024000,2048000,2400000})rate->addItem(QString::number(r)+" éch/s",r);int selected=rate->findData(s.value("rx/rate",hack?2000000:240000));rate->setCurrentIndex(qMax(0,selected));form->addRow("Taux IQ",rate);
 auto bandwidth=new QSpinBox;bandwidth->setRange(0,20000000);bandwidth->setSpecialValueText("Automatique pilote");bandwidth->setValue(s.value("rx/bandwidth",0).toInt());form->addRow("Filtre matériel Hz",bandwidth);auto channel=new QSpinBox;channel->setRange(8000,40000);channel->setValue(s.value("rx/channelBandwidth",21000).toInt());form->addRow("Filtre canal DSP Hz",channel);auto squelch=new QDoubleSpinBox;squelch->setRange(-160,0);squelch->setSpecialValueText("Désactivé");squelch->setValue(s.value("rx/squelch",-160).toDouble());form->addRow("Squelch puissance IQ dBFS",squelch);auto vga=new QSpinBox;vga->setRange(0,62);vga->setSingleStep(2);vga->setValue(s.value("rx/vga",20).toInt());vga->setEnabled(hack);form->addRow("Gain VGA HackRF dB",vga);auto reconnect=new QCheckBox("Reconnexion automatique au même SDR");reconnect->setChecked(s.value("rx/reconnect",true).toBool());form->addRow(reconnect);auto warning=new QLabel("RTL : gain manuel choisi au pas supporté le plus proche. HackRF : LNA par pas de 8 dB, VGA par pas de 2 dB ; correction PPM sur la fréquence demandée. Modifier ces paramètres redémarre la chaîne.");warning->setWordWrap(true);form->addRow(warning);
 auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);form->addRow(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{if(hack&&bandwidth->value()>rate->currentData().toInt()){QMessageBox::warning(&dialog,"Bande passante","La bande matérielle doit être inférieure au taux IQ.");return;}s.setValue("rx/agc",automatic->isChecked());s.setValue("rx/rate",rate->currentData());s.setValue("rx/bandwidth",bandwidth->value());s.setValue("rx/channelBandwidth",channel->value());s.setValue("rx/squelch",squelch->value());s.setValue("rx/vga",vga->value());s.setValue("rx/reconnect",reconnect->isChecked());s.sync();dialog.accept();if(radio_.isRunning())retune();});dialog.exec();
}
